Sure, I'd be happy to help you with that! Here's a Python program that meets your requirements. This program uses a dictionary to store recipes and conditional statements to search for recipes based on ingredients and cooking time.

```python
# Recipe database
recipes = {
    "Chicken Fajitas": {
        "ingredients": ["chicken", "bell peppers", "onions", "tomatoes", "cilantro", "tortillas"],
        "cooking_time": 30
    },
    "Spaghetti Bolognese": {
        "ingredients": ["spaghetti", "ground beef", "tomatoes", "onions", "garlic", "pasta sauce"],
        "cooking_time": 60
    },
    # Add more recipes here
}

def search_recipes(ingredients, cooking_time):
    """
    Search for recipes based on ingredients and cooking time.

    :param ingredients: List of ingredients to search for
    :param cooking_time: Maximum cooking time in minutes
    :return: List of recipes that match the search criteria
    """
    recipes_matching_criteria = []

    # Search for recipes with all ingredients and cooking time
    for recipe, recipe_data in recipes.items():
        if set(ingredients).issubset(recipe_data["ingredients"]) and recipe_data["cooking_time"] <= cooking_time:
            recipes_matching_criteria.append(recipe)

    return recipes_matching_criteria


if __name__ == "__main__":
    search_ingredients = "chicken"
    search_time = 30

    recipes_matching_criteria = search_recipes([search_ingredients], search_time)

    if recipes_matching_criteria:
        print(f"Recipe: {recipes_matching_criteria[0]}")
    else:
        print("No recipes found that match your search criteria.")
```

You can add more recipes to the `recipes` dictionary and modify the `search_recipes` function to search for recipes with fewer or more ingredients or cooking times.
